var zaikoStateKey = "toriyama_zaiko_state";

function getZaikoState() {
  try { return JSON.parse(localStorage.getItem(zaikoStateKey) || "{}"); }
  catch (e) { return {}; }
}

function saveZaikoState(state) {
  localStorage.setItem(zaikoStateKey, JSON.stringify(state));
}

// 店舗・品目名から「現在の実効値」を取得する（保存済みの上書きがあればそれを優先、無ければExcel由来の初期値）
function getEffectiveItem(store, masterItem) {
  var state = getZaikoState();
  var override = (state[store] && state[store][masterItem.name]) || {};
  var qty = (override.qty !== undefined && override.qty !== null) ? override.qty : masterItem.qty;
  var reorderPoint = (override.reorderPoint !== undefined && override.reorderPoint !== null) ? override.reorderPoint : 0;
  var ordered = !!override.ordered;
  return { name: masterItem.name, unitPrice: masterItem.unitPrice, qty: qty, reorderPoint: reorderPoint, ordered: ordered };
}

// 品目1件分の状態を部分更新して保存する（qty / reorderPoint / ordered のうち渡された項目だけ書き換える）
function setItemState(store, name, patch) {
  var state = getZaikoState();
  if (!state[store]) { state[store] = {}; }
  var existing = state[store][name] || {};
  var merged = { qty: existing.qty, reorderPoint: existing.reorderPoint, ordered: existing.ordered };
  for (var k in patch) { merged[k] = patch[k]; }
  state[store][name] = merged;
  saveZaikoState(state);
}

// 発注点が設定されていて、かつ現在数量がそれ以下ならアラーム対象
function isLowStock(item) {
  return item.reorderPoint > 0 && item.qty <= item.reorderPoint;
}

// 表示用の数値フォーマット（余計な小数を削る）
function formatQty(n) {
  var r = Math.round(n * 100) / 100;
  return String(r);
}
